CREATE TABLE customer_card_requests (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id NUMBER NOT NULL, card_type VARCHAR2(20) NOT NULL, status VARCHAR2(20) NOT NULL, review_comment VARCHAR2(500), reviewed_by VARCHAR2(80), reviewed_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_card_request_customer FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE INDEX idx_customer_card_request_status ON customer_card_requests(status);
